package com.hbm.client.missile.launchpad.standard;
import com.hbm.missile.completion.MissileContent;import com.hbm.missile.launchpad.standard.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.level.block.entity.BlockEntity;import snownee.jade.api.*;import snownee.jade.api.config.IPluginConfig;
@WailaPlugin public final class StandardLaunchPadJadePlugin implements IWailaPlugin{@Override public void register(IWailaCommonRegistration e){e.registerBlockDataProvider(Provider.INSTANCE,BlockEntity.class);}@Override public void registerClient(IWailaClientRegistration e){e.registerBlockComponent(Provider.INSTANCE,StandardLaunchPadBlock.class);}private enum Provider implements IServerDataProvider<BlockAccessor>,IBlockComponentProvider{INSTANCE;@Override public ResourceLocation getUid(){return MissileContent.id("launch_pad_state");}@Override public boolean shouldRequestData(BlockAccessor a){return a.getBlockState().getBlock() instanceof StandardLaunchPadBlock;}@Override public void appendServerData(CompoundTag tag,BlockAccessor a){if(!(a.getBlockState().getBlock() instanceof StandardLaunchPadBlock block))return;var pos=block.findCore(a.getLevel(),a.getPosition());if(pos!=null&&a.getLevel().getBlockEntity(pos) instanceof StandardLaunchPadBlockEntity pad){tag.putInt("hbm:pad_state",pad.state);tag.putInt("hbm:pad_delay",pad.delay);}}@Override public void appendTooltip(ITooltip tooltip,BlockAccessor a,IPluginConfig config){var data=a.getServerData();if(!data.contains("hbm:pad_state"))return;int state=data.getInt("hbm:pad_state");tooltip.add(Component.translatable(state==StandardLaunchPadBlockEntity.LOADING?"jade.hbm.launch_pad.loading":state==StandardLaunchPadBlockEntity.READY?"gui.hbm.launch_pad.ready":"gui.hbm.launch_pad.missing",data.getInt("hbm:pad_delay")));}}}
